def project_u(sp, Q, np=np):
    uu = np.linspace(0.0, 1.0, 2001)
    d = ((sp(uu) - Q) ** 2).sum(1)
    i = int(d.argmin())
    lo = uu[max(0, i - 1)]
    hi = uu[min(len(uu) - 1, i + 1)]
