def main():
    import cadquery as cq

    STEP = 1.0 / 6.0
    N = 12
    R2_THRESH = 169.0
    HALF = N - 1

    def occupancy():
        pass
        occ = [[[False] * N for _ in range(N)] for _ in range(N)]
        for i in range(N):
            ai = 2 * i - HALF
            for j in range(N):
                aij = ai * ai + (2 * j - HALF) ** 2
                for k in range(N):
                    ak = 2 * k - HALF
                    occ[i][j][k] = aij + ak * ak <= R2_THRESH
        return occ

    def layer_loops(g):
        pass
        edges = {}

        def add(p, q):
            edges.setdefault(p, []).append(q)

        for i in range(N):
            for j in range(N):
                if not g[i][j]:
                    continue
                if j == 0 or not g[i][j - 1]:
                    add((i, j), (i + 1, j))
                if i == N - 1 or not g[i + 1][j]:
                    add((i + 1, j), (i + 1, j + 1))
                if j == N - 1 or not g[i][j + 1]:
                    add((i + 1, j + 1), (i, j + 1))
                if i == 0 or not g[i - 1][j]:
                    add((i, j + 1), (i, j))

        loops = []
        seen = set()
        for start in edges:
            if start in seen:
                continue
            loop = [start]
            seen.add(start)
            p = start
            while True:
                q = edges[p][0]
                if q == start:
                    break
                loop.append(q)
                seen.add(q)
                p = q
            loops.append(loop)
        return loops

    def signed_area(loop):
        s = 0.0
        for a in range(len(loop)):
            x1, y1 = loop[a]
            x2, y2 = loop[(a + 1) % len(loop)]
            s += x1 * y2 - x2 * y1
        return 0.5 * s

    def to_pts(loop, z):
        return [cq.Vector(-1.0 + i * STEP, -1.0 + j * STEP, z) for i, j in loop]

    def prism(loop, z0):
        w = cq.Wire.makePolygon(to_pts(loop, z0), close=True)
        f = cq.Face.makeFromWires(w)
        return cq.Workplane(obj=f).extrude(STEP).val()

    occ = occupancy()
    adds = []
    cuts = []
    for k in range(N):
        g = [[occ[i][j][k] for j in range(N)] for i in range(N)]
        loops = layer_loops(g)
        if not loops:
            continue
        z0 = -1.0 + k * STEP
        for lp in loops:
            s = prism(lp, z0)
            if signed_area(lp) > 0:
                adds.append(s)
            else:
                cuts.append(s)

    body = adds[0]
    if len(adds) > 1:
        body = body.fuse(*adds[1:])
    if cuts:
        body = body.cut(*cuts)
    try:
        body = body.clean()
    except Exception:
        pass
    return cq.Workplane(obj=body)


