def build():
    import math
    import cadquery as cq

    yA, RA = -1.0, 0.801881
    yB, RB_outer, RB_inner = -0.928979, 0.737731, 0.515668
    yC, RC_outer, RC_inner = -0.888885, 0.515668, 0.472271
    yD, RD_outer, RD_inner = 0.961703, 0.102383, 0.076619
    yE, RE = 1.0, 0.076619

    def P(R, y, k):
        a = math.radians(45.0 * k)
        return cq.Vector(R * math.cos(a), y, R * math.sin(a))

    def wire(pts):
        return cq.Wire.makePolygon(pts, close=True)

    def octw(R, y, rev):
        ks = list(range(8))
        if rev:
            ks.reverse()
        return wire([P(R, y, k) for k in ks])

    def side_quad(R0, y0, R1, y1, k):
        return cq.Face.makeFromWires(
            wire([P(R0, y0, k), P(R1, y1, k),
                  P(R1, y1, k + 1), P(R0, y0, k + 1)]))

    def annulus(Ro, Ri, y):
        return cq.Face.makeFromWires(octw(Ro, y, True), [octw(Ri, y, False)])

    faces = []
    bands = [(RA, yA, RB_outer, yB),
             (RB_inner, yB, RC_outer, yC),
             (RC_inner, yC, RD_outer, yD),
             (RD_inner, yD, RE, yE)]
    for R0, y0, R1, y1 in bands:
        for k in range(8):
            faces.append(side_quad(R0, y0, R1, y1, k))
    for Ro, Ri, y in ((RB_outer, RB_inner, yB),
                      (RC_outer, RC_inner, yC),
                      (RD_outer, RD_inner, yD)):
        faces.append(annulus(Ro, Ri, y))
    faces.append(cq.Face.makeFromWires(octw(RA, yA, False)))
    faces.append(cq.Face.makeFromWires(octw(RE, yE, True)))

    return cq.Solid.makeSolid(cq.Shell.makeShell(faces))


result = build()

