def _build(cq):
    def _lin(chain, s):
        pass
        if s <= chain[0][0]:
            return chain[0][1]
        for (x0, h0), (x1, h1) in zip(chain, chain[1:]):
            if s <= x1:
                return h0 + (h1 - h0) * (s - x0) / (x1 - x0)
        return chain[-1][1]

    ROOF = 0.80820

    Y_OUT = 0.33025
    Y_IN_N = -0.2709
    Y_IN_P = 0.3006
    Y_BOT_N = -0.1272
    Y_BOT_P = 0.1215
    WALL_END = 0.9161
    VOID_END = 0.979

    WALL_TOP = [(0.0073, 0.4032), (0.1454, 0.4300), (0.1585, 0.4353),
                (0.2766, 0.5118), (0.2867, 0.5217), (0.3077, 0.5007),
                (0.3916, 0.4167), (0.8112, -0.0033), (0.8951, -0.0872),
                (0.9161, -0.1082)]
    CREST = [(0.0053, 0.5219), (0.1029, 0.5408), (0.1122, 0.5446),
             (0.1956, 0.5987), (0.2028, 0.6055)]
    WALL_BOT = [(0.0226, -0.4871), (0.4642, -0.4014), (0.5061, -0.3845),
                (0.8835, -0.1396), (0.9161, -0.1082)]
    BOTTOM = [(0.0245, -0.6058), (0.5067, -0.5123), (0.5525, -0.4938),
              (0.9645, -0.2265), (1.0, -0.1922)]
    IN_TOP = [(0.0073, 0.3735), (0.1561, 0.4023), (0.1701, 0.4079),
              (0.2968, 0.4901), (0.3077, 0.5007)]
    IN_CEIL = [(0.0055, 0.4922), (0.1133, 0.5132), (0.1235, 0.5173),
               (0.2155, 0.5771), (0.2234, 0.5847)]
    IN_WBOT = [(0.0220, -0.4574), (0.4535, -0.3737), (0.4945, -0.3572),
               (0.8633, -0.1179), (0.8951, -0.0872)]
    IN_BOT = [(0.0240, -0.5761), (0.4960, -0.4846), (0.5409, -0.4665),
              (0.9442, -0.2048), (0.979, -0.1712)]

    def wall_top(s):
        return _lin(WALL_TOP, s) if s <= WALL_END else ROOF - s

    def wall_bot(s):
        return _lin(WALL_BOT, s) if s <= WALL_END else ROOF - s

    def crest(s):
        return min(ROOF - s, _lin(CREST, s))

    def bottom(s):
        return _lin(BOTTOM, s)

    def in_wtop(s):
        return min(ROOF - s, _lin(IN_TOP, s))

    def in_ceil(s):
        return min(ROOF - s, _lin(IN_CEIL, s))

    def in_wbot(s):
        return min(ROOF - s, _lin(IN_WBOT, s))

    def in_bot(s):
        return _lin(IN_BOT, s)

    def y_outer(s, pos):
        pass
        if s <= WALL_END:
            return Y_OUT if pos else -Y_OUT
        t = (s - WALL_END) / (1.0 - WALL_END)
        if pos:
            return Y_IN_P + t * (Y_BOT_P - Y_IN_P)
        return Y_IN_N + t * (Y_BOT_N - Y_IN_N)

    def shelf(s):
        pass
        sp = min(Y_BOT_P + 2.135 * max(0.0, s - 0.2028), Y_IN_P - 0.0008)
        sn = max(Y_BOT_N - 1.711 * max(0.0, s - 0.2021), Y_IN_N + 0.0008)
        return sn, sp

    def outer_section(x):
        s = abs(x)
        wt, wb = wall_top(s), wall_bot(s)
        co, zb = crest(s), bottom(s)
        ya = min(y_outer(s, False), Y_BOT_N - 0.0004)
        yf = max(y_outer(s, True), Y_BOT_P + 0.0004)
        yb = min(Y_BOT_N - 0.0006, max(Y_IN_N, ya + 0.0008))
        ye = max(Y_BOT_P + 0.0006, min(Y_IN_P, yf - 0.0008))
        if wt - wb < 0.0006:
            wb = wt - 0.0006
        sn, sp = shelf(s)
        sn = min(max(sn, yb + 0.0004), Y_BOT_N)
        sp = max(min(sp, ye - 0.0004), Y_BOT_P)
        return [(ya, wb), (ya, wt), (yb, wt), (sn, co), (sp, co), (ye, wt),
                (yf, wt), (yf, wb), (ye, wb), (Y_BOT_P, zb),
                (Y_BOT_N, zb), (yb, wb)]

    OPEN_X = 0.2238
    LIP_X = 0.3077
    LIFT = 0.01

    def ceiling(s):
        pass
        if s <= OPEN_X:
            return Y_BOT_N, Y_BOT_P, min(in_ceil(s), ROOF - s - 0.0002)
        t = min(1.0, (s - OPEN_X) / (LIP_X - OPEN_X))
        return (Y_BOT_N + t * (Y_IN_N - Y_BOT_N),
                Y_BOT_P + t * (Y_IN_P - Y_BOT_P), ROOF - s + LIFT)

    def inner_section(x):
        s = abs(x)
        tw, tb = in_wtop(s), in_wbot(s)
        ib = in_bot(s)
        if s <= 0.8951:
            yl, yr = Y_IN_N, Y_IN_P
        else:
            t = (s - 0.8951) / (VOID_END - 0.8951)
            yl = Y_IN_N + t * (Y_BOT_N - Y_IN_N)
            yr = Y_IN_P + t * (Y_BOT_P - Y_IN_P)
        if tw - tb < 0.0006:
            tb = tw - 0.0006
        a, b, cc = ceiling(s)
        a = max(a, yl + 0.0015)
        b = min(b, yr - 0.0015)
        return [(yl, tb), (yl, tw), (a, cc), (b, cc), (yr, tw),
                (yr, tb), (Y_BOT_P, ib), (Y_BOT_N, ib)]

    def loft(section, stations):
        xs = [-s for s in reversed(stations) if s > 0.0] + list(stations)
        wires = [cq.Wire.makePolygon(
            [cq.Vector(x, y, z) for (y, z) in section(x)], close=True)
            for x in xs]
        return cq.Solid.makeLoft(wires, ruled=True)

    def stations(chains, extra, limit):
        pts = set([0.0])
        for c in chains:
            pts.update(p[0] for p in c)
        pts.update(extra)
        return sorted(p for p in pts if p <= limit)

    hull_st = stations([WALL_TOP, CREST, WALL_BOT, BOTTOM],
                       [0.2021, 0.2861, WALL_END + 5e-5, 0.9995], 0.9995)
    void_st = stations([IN_TOP, IN_CEIL, IN_WBOT, IN_BOT],
                       [OPEN_X, 0.976], 0.976)

    outer = loft(outer_section, hull_st)
    void = loft(inner_section, void_st)
    return outer.cut(void)


result = _build(cq)

