from OCP.BRepBuilderAPI import (BRepBuilderAPI_Sewing, BRepBuilderAPI_MakeFace,
                                BRepBuilderAPI_MakePolygon)
from OCP.BRepAlgoAPI import BRepAlgoAPI_Splitter
from OCP.TopTools import TopTools_ListOfShape
from OCP.TColgp import TColgp_Array2OfPnt
from OCP.TColStd import TColStd_Array1OfReal, TColStd_Array1OfInteger
from OCP.Geom import Geom_BSplineSurface
from OCP.gp import gp_Pnt

P = np.array([
    [ 0.71833563, -0.32424438,  0.57794100],
    [ 0.90561140, -0.28496557,  0.13430798],
    [ 1.00000000,  0.04347107,  0.05861479],
    [ 0.88298446,  0.32993263, -0.16238444],
    [ 0.41943848, -0.69896591,  0.51736355],
    [ 0.35961398,  0.69451219,  0.05861479],
    [ 0.14404061, -0.68536037,  0.73295623],
    [-0.22956149, -0.61734408,  0.71433562],
    [-0.42287841,  0.02824106,  0.67529696],
    [-0.89030290, -0.24844405,  0.27450356],
    [-1.00000000, -0.04653548, -0.02847002],
    [-0.88355345,  0.02862938, -0.34987280],
    [-0.73284328,  0.48608479, -0.38790312],
    [-0.39746097,  0.44269827, -0.73295623],
    [-0.14425404,  0.68247736, -0.70292997],
    [ 0.22206093,  0.69896591, -0.60225731]])

hull = ConvexHull(P)
tris = hull.simplices
eqs = hull.equations

G = []
for i in range(len(tris)):
    hit = False
    for g in G:
        if eqs[i, :3] @ eqs[g[0], :3] > 0.9999 and abs(eqs[i, 3] - eqs[g[0], 3]) < 5e-4:
            g.append(i)
            hit = True
            break
    if not hit:
        G.append([i])
NF = len(G)
nrm = np.zeros((NF, 3))
for fi in range(NF):
    n = eqs[G[fi][0], :3].copy()
    nrm[fi] = n / np.linalg.norm(n)

FED = []
for fi in range(NF):
    cnt = {}
    for k in G[fi]:
        t = tris[k]
        for j in range(3):
            a = int(t[j]); b = int(t[(j + 1) % 3])
            e = (a, b) if a < b else (b, a)
            cnt[e] = cnt.get(e, 0) + 1
    ed = []
    for e in cnt:
        if cnt[e] == 1:
            ed.append(e)
    FED.append(ed)

pairs = {}
for a in range(NF):
    sa = set(FED[a])
    for b in range(a + 1, NF):
        if len(sa.intersection(FED[b])) > 0:
            pairs[(a, b)] = float(np.degrees(np.arccos(
                max(-1.0, min(1.0, float(nrm[a] @ nrm[b]))))))
par = list(range(NF))
for (a, b) in pairs:
    if 0.5 < pairs[(a, b)] < 25.0:
        x = a
        while par[x] != x:
            x = par[x]
        y = b
        while par[y] != y:
            y = par[y]
        if x != y:
            par[x] = y
comp = {}
for f in range(NF):
    x = f
    while par[x] != x:
        x = par[x]
    if x in comp:
        comp[x].append(f)
    else:
        comp[x] = [f]
bands = []
flats = []
for r in comp:
    if len(comp[r]) >= 2:
        bands.append(comp[r])
    else:
        flats.append(comp[r][0])

faces = []

for fi in flats:
    n = nrm[fi]
    ids = []
    for e in FED[fi]:
        if e[0] not in ids:
            ids.append(e[0])
        if e[1] not in ids:
            ids.append(e[1])
    pts = P[ids]
    c = pts.mean(axis=0)
    pts = pts - ((pts - c) @ n)[:, None] * n
    a = np.cross(n, [0.0, 0.0, 1.0])
    if np.linalg.norm(a) < 1e-6:
        a = np.cross(n, [1.0, 0.0, 0.0])
    a /= np.linalg.norm(a)
    b = np.cross(n, a)
    q = pts - c
    order = np.argsort(np.arctan2(q @ b, q @ a))
    loop = []
    for k in order:
        loop.append(cq.Vector(float(pts[k, 0]), float(pts[k, 1]), float(pts[k, 2])))
    faces.append(cq.Face.makeFromWires(cq.Wire.makePolygon(loop, close=True)))

for m in bands:
    cnt = {}
    own = {}
    for f in m:
        for e in FED[f]:
            cnt[e] = cnt.get(e, 0) + 1
            if e in own:
                own[e].append(f)
            else:
                own[e] = [f]
    folds = []
    be = []
    for e in cnt:
        if cnt[e] == 2:
            folds.append(e)
        else:
            be.append(e)

    nb = {}
    for e in be:
        if e[0] in nb:
            nb[e[0]].append(e)
        else:
            nb[e[0]] = [e]
        if e[1] in nb:
            nb[e[1]].append(e)
        else:
            nb[e[1]] = [e]
    loop = [be[0][0], be[0][1]]
    while True:
        cur = loop[-1]
        prev = loop[-2]
        nxt = -1
        for e in nb[cur]:
            o = e[0] if e[1] == cur else e[1]
            if o != prev:
                nxt = o
        if nxt == loop[0]:
            break
        loop.append(nxt)

    fv = set()
    for e in folds:
        fv.add(e[0]); fv.add(e[1])
    tips = []
    for v in loop:
        if v not in fv:
            tips.append(v)

    iA = loop.index(tips[0])
    iB = loop.index(tips[1])
    if iA > iB:
        iA, iB = iB, iA
    rail1 = loop[iA:iB + 1]
    rail2 = [loop[iA]]
    j = iA
    while j != iB:
        j = (j - 1) % len(loop)
        rail2.append(loop[j])

    fadj = {}
    for f in m:
        fadj[f] = []
    for e in folds:
        o = own[e]
        fadj[o[0]].append([o[1], e])
        fadj[o[1]].append([o[0], e])
    cur = -1
    for f in m:
        if len(fadj[f]) == 1:
            ids = []
            for e in FED[f]:
                if e[0] not in ids:
                    ids.append(e[0])
                if e[1] not in ids:
                    ids.append(e[1])
            if tips[0] in ids:
                cur = f
    if cur == -1:
        cur = m[0]
    prevf = -1
    seq = []
    while cur != -1:
        nxt = -1
        nedge = None
        for pair in fadj[cur]:
            if pair[0] != prevf:
                nxt, nedge = pair[0], pair[1]
        if nedge is not None:
            seq.append(nedge)
        prevf = cur
        cur = nxt

    S1 = [P[rail1[0]]]
    S2 = [P[rail2[0]]]
    for e in seq:
        if e[0] in rail1:
            S1.append(P[e[0]])
            S2.append(P[e[1]])
        else:
            S1.append(P[e[1]])
            S2.append(P[e[0]])
    S1.append(P[rail1[-1]])
    S2.append(P[rail2[-1]])

    nst = len(S1)
    cen = P.mean(axis=0)
    k0 = nst // 2
    du = S1[min(k0 + 1, nst - 1)] - S1[max(k0 - 1, 0)]
    dv = S2[k0] - S1[k0]
    nv = np.cross(du, dv)
    q = 0.5 * (S1[k0] + S2[k0]) - cen
    if float(nv @ q) < 0.0:
        tmp = S1
        S1 = S2
        S2 = tmp

    poles = TColgp_Array2OfPnt(1, nst, 1, 2)
    for k in range(nst):
        poles.SetValue(k + 1, 1, gp_Pnt(float(S1[k][0]), float(S1[k][1]), float(S1[k][2])))
        poles.SetValue(k + 1, 2, gp_Pnt(float(S2[k][0]), float(S2[k][1]), float(S2[k][2])))
    ku = TColStd_Array1OfReal(1, nst)
    mu = TColStd_Array1OfInteger(1, nst)
    ku.SetValue(1, 0.0); mu.SetValue(1, 2)
    for k in range(1, nst - 1):
        ku.SetValue(k + 1, float(k) / float(nst - 1)); mu.SetValue(k + 1, 1)
    ku.SetValue(nst, 1.0); mu.SetValue(nst, 2)
    kv = TColStd_Array1OfReal(1, 2)
    kv.SetValue(1, 0.0); kv.SetValue(2, 1.0)
    mv = TColStd_Array1OfInteger(1, 2)
    mv.SetValue(1, 2); mv.SetValue(2, 2)
    surf = Geom_BSplineSurface(poles, ku, kv, mu, mv, 1, 1)
    full = BRepBuilderAPI_MakeFace(surf, 1e-9).Face()

    wp = BRepBuilderAPI_MakePolygon()
    for vv in loop:
        wp.Add(gp_Pnt(float(P[vv][0]), float(P[vv][1]), float(P[vv][2])))
    wp.Close()
    args = TopTools_ListOfShape(); args.Append(full)
    tools = TopTools_ListOfShape(); tools.Append(wp.Wire())
    sp = BRepAlgoAPI_Splitter(); sp.SetArguments(args); sp.SetTools(tools); sp.Build()
    bf = cq.Shape.cast(full)
    if sp.IsDone():
        best = None
        ba = -1.0
        for g2 in cq.Shape.cast(sp.Shape()).Faces():
            if g2.Area() > ba:
                ba = g2.Area()
                best = g2
        if best is not None:
            bf = best
    faces.append(bf)

sew = BRepBuilderAPI_Sewing(1e-3)
for f in faces:
    sew.Add(f.wrapped)
sew.Perform()
result = cq.Solid.makeSolid(cq.Shell.cast(sew.SewedShape()))
